import { pandianTaskDeviceInfo, pandianTaskDeviceApprove } from "@/api/shujubaoxian/pandianTask";
export default {
  props: ['isShow', 'taskId', 'onlyRead', 'filingNo'],
  data: function data() {
    return {
      form: {
        opearteResult: ''
      },
      comment: '',
      isApproval: false
    };
  },
  methods: {
    submitOperate: function submitOperate() {
      var _this = this;
      if (this.onlyRead) {
        this.$emit('close');
        return;
      }
      pandianTaskDeviceApprove({
        id: this.taskId,
        disposeResult: this.form.opearteResult,
        editType: '0',
        disComment: this.comment,
        filingNo: this.filingNo,
        workerStatus: this.form.opearteResult == 1 ? '0' : '1'
      }).then(function (res) {
        if (res.code == 200) {
          _this.$message({
            type: "success",
            message: "处置成功!"
          });
          _this.$emit('refresh');
        }
      }).catch(function (err) {
        // console.log(err,'错误信息=============');
      });
    },
    loadDetail: function loadDetail() {
      var _this2 = this;
      pandianTaskDeviceInfo({
        id: this.taskId,
        editType: '1'
      }).then(function (res) {
        if (res.code == 200) {
          _this2.form = res.data;
          _this2.tableData = JSON.parse(res.data.changeContent);
          _this2.tableData = _this2.tableData.filter(function (item) {
            return item.property.includi;
          });
          //  console.log(this.tableData);
        }
      });
    }
  },
  mounted: function mounted() {
    this.loadDetail();
  }
};
